import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useLocation } from 'react-router-dom';
import { Modal } from 'react-bootstrap';
import { KTIcon, exportToExcel, exportToCsv } from '../../../_metronic/helpers';
import { PageTitle } from '../../../_metronic/layout/core';

interface Product {
    id: number;
    sku: string;
    name: string;
    price: number;
    status: number;
    type_id: string;
    created_at: string;
    updated_at: string;
    seller_name?: string;
}

const ProductsPage: React.FC = () => {
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [typeFilter, setTypeFilter] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const [totalCount, setTotalCount] = useState(0);
    const [showExportModal, setShowExportModal] = useState<boolean>(false);
    const [itemsPerPage, setItemsPerPage] = useState<number>(10);

    const fetchProducts = () => {
        setLoading(true);
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
        axios.get(`${apiUrl}/magento/products`, {
            params: {
                page: currentPage,
                limit: itemsPerPage
            }
        })
            .then(response => {
                setProducts(response.data.items || []);
                setTotalCount(response.data.total_count || 0);
                setLoading(false);
            })
            .catch(err => {
                console.error("Error fetching products:", err);
                setError("Failed to fetch products");
                setLoading(false);
            });
    };

    useEffect(() => {
        fetchProducts();
        // Remove interval for now as it disrupts pagination if not carefully managed
        // return () => clearInterval(interval);
    }, [currentPage, itemsPerPage]);

    // Handle URL parameters for search auto-fill
    const location = useLocation();
    useEffect(() => {
        const queryParams = new URLSearchParams(location.search);
        const sku = queryParams.get('sku') || queryParams.get('search');
        if (sku) {
            setSearchTerm(sku);
            setCurrentPage(1);
        }
    }, [location.search]);

    // Client-side filtering is applied to the CURRENT PAGE only
    const currentProducts = products.filter(product => {
        const matchesSearch =
            product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            product.sku.toLowerCase().includes(searchTerm.toLowerCase());

        const matchesType = typeFilter === 'all' || product.type_id === typeFilter;

        return matchesSearch && matchesType;
    });

    const totalPages = Math.ceil(totalCount / itemsPerPage);
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;

    const getStatusBadgeClass = (status: number) => {
        return status === 1 ? 'badge-light-success' : 'badge-light-danger';
    };

    const getStatusText = (status: number) => {
        return status === 1 ? 'Enabled' : 'Disabled';
    };




    const getExportData = () => {
        return currentProducts.map(product => ({
            "Product": product.name,
            "SKU": product.sku,
            "Price": parseFloat(product.price.toString()).toFixed(2),
            "Status": getStatusText(product.status),
            "Seller": product.seller_name || 'N/A',
            "Updated": new Date(product.updated_at).toLocaleDateString()
        }));
    };

    const handleExportCsv = () => {
        const dataToExport = getExportData();
        exportToCsv(dataToExport, 'products_export');
        setShowExportModal(false);
    };

    const handleExportXls = () => {
        const dataToExport = getExportData();
        exportToExcel(dataToExport, 'products_export', 'Products');
        setShowExportModal(false);
    };

    if (error) {
        return (
            <div className="alert alert-danger" role="alert">
                <KTIcon iconName="information" className="fs-2 me-2" />
                {error}
            </div>
        );
    }

    return (
        <>
            <PageTitle breadcrumbs={[]}>Products Catalog</PageTitle>
            <div className="card">
                {/* Header */}
                <div className="card-header border-0 pt-6">
                    <div className="card-title">
                        {/* Search */}
                        <div className="d-flex align-items-center position-relative my-1">
                            <KTIcon iconName="magnifier" className="fs-1 position-absolute ms-6" />
                            <input
                                type="text"
                                data-kt-product-table-filter="search"
                                className="form-control form-control-solid w-250px ps-14"
                                placeholder="Search products..."
                                value={searchTerm}
                                onChange={(e) => {
                                    setSearchTerm(e.target.value);
                                    setCurrentPage(1);
                                }}
                            />
                        </div>
                    </div>
                    <div className="card-toolbar">
                        <div className="d-flex justify-content-end align-items-center gap-2">
                            {/* Export Button */}
                            <button
                                type="button"
                                className="btn btn-light-primary me-3"
                                onClick={() => setShowExportModal(true)}
                            >
                                <KTIcon iconName="exit-up" className="fs-2" />
                                Export
                            </button>

                            {/* Type Filter */}
                            <select
                                className="form-select form-select-solid w-150px"
                                value={typeFilter}
                                onChange={(e) => {
                                    setTypeFilter(e.target.value);
                                    setCurrentPage(1);
                                }}
                            >
                                <option value="all">All Types</option>
                                <option value="simple">Simple</option>
                                <option value="configurable">Configurable</option>
                                <option value="virtual">Virtual</option>
                                <option value="bundle">Bundle</option>
                                <option value="downloadable">Downloadable</option>
                            </select>
                        </div>
                    </div>
                </div>

                {/* Body */}
                <div className="card-body py-4">
                    {/* Results Info */}
                    <div className="mb-5">
                        <div className="text-gray-600 fw-semibold fs-7">
                            Showing {indexOfFirstItem + 1} to {Math.min(indexOfLastItem, totalCount)} of {totalCount} products
                        </div>
                    </div>

                    {/* Table */}
                    <div className="table-responsive">
                        <table className="table align-middle table-row-dashed fs-6 gy-5">
                            <thead>
                                <tr className="text-start text-muted fw-bold fs-7 text-uppercase gs-0">
                                    <th className="min-w-125px">Product</th>
                                    <th className="min-w-100px">SKU</th>

                                    <th className="min-w-100px">Price</th>
                                    <th className="min-w-100px">Status</th>
                                    <th className="min-w-100px">Seller</th>
                                    <th className="min-w-125px">Updated</th>
                                </tr>
                            </thead>
                            <tbody className="text-gray-600 fw-semibold">
                                {loading ? (
                                    [...Array(5)].map((_, index) => (
                                        <tr key={`skeleton-${index}`}>
                                            <td>
                                                <div className="d-flex align-items-center">
                                                    <div className="symbol symbol-50px me-3">
                                                        <div className="symbol-label placeholder-glow">
                                                            <span className="placeholder w-100 h-100 rounded"></span>
                                                        </div>
                                                    </div>
                                                    <div className="d-flex flex-column wrapper placeholder-glow w-75">
                                                        <span className="placeholder col-12 mb-1"></span>
                                                        <span className="placeholder col-6"></span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td><span className="placeholder-glow"><span className="placeholder col-8"></span></span></td>

                                            <td><span className="placeholder-glow"><span className="placeholder col-4"></span></span></td>
                                            <td><span className="placeholder-glow"><span className="placeholder col-8 py-2 rounded"></span></span></td>
                                            <td><span className="placeholder-glow"><span className="placeholder col-6"></span></span></td>
                                            <td><span className="placeholder-glow"><span className="placeholder col-6"></span></span></td>
                                        </tr>
                                    ))
                                ) : currentProducts.length === 0 ? (
                                    <tr>
                                        <td colSpan={7} className="text-center py-10">
                                            <div className="d-flex flex-column align-items-center">
                                                <KTIcon iconName="package" className="fs-3x text-gray-400 mb-3" />
                                                <span className="text-gray-500">No products found</span>
                                            </div>
                                        </td>
                                    </tr>
                                ) : (
                                    currentProducts.map(product => (
                                        <tr key={product.id}>
                                            <td>
                                                <div className="d-flex align-items-center">
                                                    <div className="symbol symbol-50px me-3">
                                                        <div className="symbol-label bg-light-info">
                                                            <KTIcon iconName="package" className="fs-2x text-info" />
                                                        </div>
                                                    </div>
                                                    <div className="d-flex flex-column">
                                                        <span className="text-gray-800 fw-bold mb-1">{product.name}</span>
                                                        <span className="text-muted fs-7">ID: {product.id}</span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td>
                                                <span className="badge badge-light-primary">{product.sku}</span>
                                            </td>

                                            <td className="text-success fw-bold">
                                                ${parseFloat(product.price.toString()).toFixed(2)}
                                            </td>
                                            <td>
                                                <span className={`badge ${getStatusBadgeClass(product.status)} fw - bold`}>
                                                    {getStatusText(product.status)}
                                                </span>
                                            </td>
                                            <td>
                                                <span className="text-gray-800 fw-bold">
                                                    {product.seller_name || 'N/A'}
                                                </span>
                                            </td>
                                            <td>
                                                <span className="text-gray-600">
                                                    {new Date(product.updated_at).toLocaleDateString('en-US', {
                                                        year: 'numeric',
                                                        month: 'short',
                                                        day: 'numeric'
                                                    })}
                                                </span>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>

                    {/* Pagination */}
                    {totalCount > 0 && (
                        <div className="d-flex justify-content-between align-items-center mt-4 pt-10">
                            <div className="d-flex align-items-center">
                                <span className="text-gray-600 me-3 fw-semibold">Rows per page:</span>
                                <select
                                    className="form-select form-select-sm form-select-solid w-75px"
                                    value={itemsPerPage}
                                    onChange={(e) => {
                                        setItemsPerPage(Number(e.target.value));
                                        setCurrentPage(1);
                                    }}
                                >
                                    <option value={10}>10</option>
                                    <option value={20}>20</option>
                                    <option value={50}>50</option>
                                    <option value={100}>100</option>
                                </select>
                            </div>

                            <div className="d-flex align-items-center">
                                <button
                                    className="btn btn-sm btn-light-primary me-3"
                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                    disabled={currentPage === 1}
                                >
                                    <KTIcon iconName="arrow-left" className="fs-3 me-1" />
                                    Previous
                                </button>

                                <span className="fw-bold text-gray-600 me-3">
                                    Page {currentPage} of {Math.max(1, totalPages)}
                                </span>

                                <button
                                    className="btn btn-sm btn-light-primary"
                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                    disabled={currentPage === totalPages || totalPages === 0}
                                >
                                    Next
                                    <KTIcon iconName="arrow-right" className="fs-3 ms-1" />
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div >

            <Modal show={showExportModal} onHide={() => setShowExportModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Export Options</Modal.Title>
                </Modal.Header>
                <Modal.Body className="text-center py-10">
                    <p className="text-gray-600 mb-8 fs-5">Choose the format you want to export the data in:</p>
                    <div className="d-flex justify-content-center gap-4">
                        <button className="btn btn-outline btn-outline-dashed btn-outline-success btn-active-light-success px-10 py-5" onClick={handleExportCsv}>
                            <i className="bi bi-filetype-csv fs-1 mb-2 d-block"></i>
                            <span className="fw-bold fs-5">CSV</span>
                        </button>
                        <button className="btn btn-outline btn-outline-dashed btn-outline-primary btn-active-light-primary px-10 py-5" onClick={handleExportXls}>
                            <i className="bi bi-filetype-xls fs-1 mb-2 d-block"></i>
                            <span className="fw-bold fs-5">XLS</span>
                        </button>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default ProductsPage;
